41.         Action<string> onOutput,
42.         CancellationToken cancellationToken = default)
43.     {
44.         AppLogger.Info($"CommitAsync starting for repo '{repo.Name}', ACD: {repo.AcdFilePath}");
45. 
46.         var validationResult = ValidatePaths(repo, l5xGitExePath, onOutput);
47.         if (validationResult != L5xGitOperationResult.Succeeded)
48.         {
49.             AppLogger.Warn($"CommitAsync aborted — path validation failed for repo '{repo.Name}'.");
50.             return validationResult;
51.         }
52. 
53.         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);
54. 
55.         // Blank line after the message signals end-of-input to PromptForCommitMessage.
56.         var stdin = commitMessage.Trim() + "\n\n";
57. 
