442.         {
443.             if (e.Data is not null) onOutput(e.Data);
444.         };
445.         process.ErrorDataReceived += (_, e) =>
446.         {
447.             if (e.Data is null) return;
448.             onOutput($"[stderr] {e.Data}");
449.             EmitLogixSdkCompatibilityHint(e.Data, onOutput);
