451. 
452.         process.Start();
453.         process.BeginOutputReadLine();
454.         process.BeginErrorReadLine();
455. 
456.         if (stdinInput is not null)
457.             await process.StandardInput.WriteAsync(stdinInput);
458. 
459.         process.StandardInput.Close();
460. 
461.         await process.WaitForExitAsync(cancellationToken);
462. 
