     /// prevents shell injection and handles paths with spaces without manual quoting.
     /// </remarks>
     private static async Task<int> RunProcessAsync(
         string exePath,
         IEnumerable<string> arguments,
         string? stdinInput,
         Action<string> onOutput,
         CancellationToken cancellationToken)
     {
         var argList = arguments.ToList();
         AppLogger.Info($"Launching: {exePath} {string.Join(" ", argList.Select(a => $"\"{a}\""))}");

         var psi = new ProcessStartInfo(exePath)
         {
             RedirectStandardInput = true,
             RedirectStandardOutput = true,
             RedirectStandardError = true,
             UseShellExecute = false,
             CreateNoWindow = true,
         };

         foreach (var arg in argList)
             psi.ArgumentList.Add(arg);

         using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };

         process.OutputDataReceived += (_, e) =>
         {
             if (e.Data is not null) onOutput(e.Data);
         };
         process.ErrorDataReceived += (_, e) =>
         {
             if (e.Data is null) return;
             onOutput($"[stderr] {e.Data}");
             EmitLogixSdkCompatibilityHint(e.Data, onOutput);
         };

         process.Start();
         process.BeginOutputReadLine();
         process.BeginErrorReadLine();

         if (stdinInput is not null)
             await process.StandardInput.WriteAsync(stdinInput);

         process.StandardInput.Close();

         await process.WaitForExitAsync(cancellationToken);

         if (process.ExitCode != 0)
         {
             onOutput($"[exit code {process.ExitCode}] Process finished with errors.");
             AppLogger.Warn($"Process '{exePath}' exited with code {process.ExitCode}.");
         }
         else
         {
             onOutput("[done] ✓ Completed successfully.");
             AppLogger.Info($"Process '{exePath}' completed successfully.");
         }

         return process.ExitCode;
     }
