183.         AppendLog($"--- Commit started: {SelectedRepo.Name} ---");
184.         AppLogger.Info($"CommitAsync initiated by user for repo '{SelectedRepo.Name}'.");
185.         _cts = new CancellationTokenSource();
186. 
187.         try
188.         {
189.             var result = await _cliService.CommitAsync(
190.                 repo: SelectedRepo.ToModel(),
191.                 l5xGitExePath: L5xGitExePath,
